from collections import deque
def find_shapes(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==c and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                ys=[y for y,x in cells]; xs=[x for y,x in cells]
                my,mx=min(ys),min(xs)
                out.append({'color':c,'cells':tuple(sorted((y-my,x-mx) for y,x in cells)),
                            'size':len(cells),'h':max(ys)-my+1,'w':max(xs)-mx+1,
                            'top':my,'left':mx})
    return out

def transform(g):
    shapes=find_shapes(g)
    bycolor={}
    for s in shapes: bycolor.setdefault(s['color'],[]).append(s)
    cols=sorted(bycolor)
    A,B=cols[0],cols[1]
    sa=sorted(bycolor[A],key=lambda s:s['size'])
    sb=sorted(bycolor[B],key=lambda s:s['size'])
    pairs=[]
    for a,b in zip(sa,sb):
        # smaller size on left; tie -> shape appearing first (top-left) in input, then lower color
        l,r=sorted([a,b],key=lambda s:(s['size'],s['top'],s['left'],s['color']))
        pairs.append((l,r))
    pairs.sort(key=lambda p:max(p[0]['size'],p[1]['size']))
    H=len(g); W=len(g[0])
    out=[[0]*W for _ in range(H)]
    R=1+max(p[0]['w'] for p in pairs)
    bottom=H-1
    for l,r in pairs:
        bh=max(l['h'],r['h'])
        top=bottom-bh+1
        for s,c0 in ((l,0),(r,R)):
            for y,x in s['cells']:
                # bottom-align: shape bottom at band bottom
                out[top+bh-s['h']+y][c0+x]=s['color']
        bottom=top-2  # one blank row gap
    return out

